import pandas as pd
import numpy as np
from scipy import stats
import json
import os

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv("/app/benchmark/data.csv")
df.columns = df.columns.str.strip()

# Normalize genre spelling
df["Genre"] = df["Genre"].str.strip()

# ── 1. Market Overview ────────────────────────────────────────────────────
total_records = len(df)
unique_books = df["Name"].nunique()
unique_authors = df["Author"].nunique()
avg_price = df["Price"].mean()
avg_rating = df["User Rating"].mean()
total_reviews = df["Reviews"].sum()
avg_reviews = df["Reviews"].mean()
genre_counts = df["Genre"].value_counts()
fiction_count = genre_counts.get("Fiction", 0)
nonfiction_count = genre_counts.get("Non Fiction", 0)
year_range = f"{df['Year'].min()}–{df['Year'].max()}"

# ── 2. Price-Rating Correlation ───────────────────────────────────────────
pearson_r, pearson_p = stats.pearsonr(df["Price"], df["User Rating"])
spearman_r, spearman_p = stats.spearmanr(df["Price"], df["User Rating"])

# Price segments
def price_segment(p):
    if p == 0:
        return "Free ($0)"
    elif p <= 5:
        return "Budget ($1–5)"
    elif p <= 10:
        return "Mid-Low ($6–10)"
    elif p <= 15:
        return "Mid ($11–15)"
    elif p <= 25:
        return "Mid-High ($16–25)"
    else:
        return "Premium ($26+)"

df["PriceSegment"] = df["Price"].apply(price_segment)
segment_order = ["Free ($0)", "Budget ($1–5)", "Mid-Low ($6–10)", "Mid ($11–15)", "Mid-High ($16–25)", "Premium ($26+)"]
segment_stats = df.groupby("PriceSegment").agg(
    count=("Price", "size"),
    avg_rating=("User Rating", "mean"),
    avg_price=("Price", "mean"),
    avg_reviews=("Reviews", "mean")
).reindex(segment_order)

# ── 3. Genre Comparison ──────────────────────────────────────────────────
genre_stats = df.groupby("Genre").agg(
    count=("Price", "size"),
    avg_price=("Price", "mean"),
    median_price=("Price", "median"),
    avg_rating=("User Rating", "mean"),
    avg_reviews=("Reviews", "mean"),
    total_reviews=("Reviews", "sum"),
    min_price=("Price", "min"),
    max_price=("Price", "max"),
    min_rating=("User Rating", "min"),
    max_rating=("User Rating", "max")
)

# ── 4. Temporal Trends ───────────────────────────────────────────────────
yearly = df.groupby("Year").agg(
    avg_price=("Price", "mean"),
    avg_rating=("User Rating", "mean"),
    avg_reviews=("Reviews", "mean"),
    total_reviews=("Reviews", "sum"),
    count=("Price", "size")
).reset_index()

yearly_genre = df.groupby(["Year", "Genre"]).agg(
    avg_price=("Price", "mean"),
    avg_rating=("User Rating", "mean"),
    avg_reviews=("Reviews", "mean"),
    count=("Price", "size")
).reset_index()

yearly_fiction = yearly_genre[yearly_genre["Genre"] == "Fiction"].set_index("Year")
yearly_nonfiction = yearly_genre[yearly_genre["Genre"] == "Non Fiction"].set_index("Year")

# Price distribution per year
yearly_price_std = df.groupby("Year")["Price"].std().reset_index()
yearly_price_std.columns = ["Year", "price_std"]

# ── 5. Top Authors ───────────────────────────────────────────────────────
author_freq = df.groupby("Author").agg(
    appearances=("Name", "size"),
    unique_books=("Name", "nunique"),
    avg_rating=("User Rating", "mean"),
    avg_price=("Price", "mean"),
    total_reviews=("Reviews", "sum")
).sort_values("appearances", ascending=False)

top_authors = author_freq.head(10).reset_index()

# ── 6. Additional computed values for recommendations ────────────────────
# Best value segment
best_value_segment = segment_stats["avg_rating"].idxmax()

# Price change over decade
price_2009 = yearly[yearly["Year"] == 2009]["avg_price"].values[0]
price_2019 = yearly[yearly["Year"] == 2019]["avg_price"].values[0]
price_change_pct = ((price_2019 - price_2009) / price_2009) * 100

rating_2009 = yearly[yearly["Year"] == 2009]["avg_rating"].values[0]
rating_2019 = yearly[yearly["Year"] == 2019]["avg_rating"].values[0]

# Genre price gap
fiction_avg_price = genre_stats.loc["Fiction", "avg_price"]
nonfiction_avg_price = genre_stats.loc["Non Fiction", "avg_price"]
genre_price_gap = abs(fiction_avg_price - nonfiction_avg_price)

fiction_avg_rating = genre_stats.loc["Fiction", "avg_rating"]
nonfiction_avg_rating = genre_stats.loc["Non Fiction", "avg_rating"]

# ── Build data JSON for JS charts ────────────────────────────────────────
chart_data = {
    "yearly": {
        "years": yearly["Year"].tolist(),
        "avg_price": [round(x, 2) for x in yearly["avg_price"].tolist()],
        "avg_rating": [round(x, 2) for x in yearly["avg_rating"].tolist()],
        "avg_reviews": [round(x, 0) for x in yearly["avg_reviews"].tolist()],
    },
    "yearly_genre": {
        "years": sorted(df["Year"].unique().tolist()),
        "fiction_price": [round(yearly_fiction.loc[y, "avg_price"], 2) if y in yearly_fiction.index else None for y in sorted(df["Year"].unique())],
        "nonfiction_price": [round(yearly_nonfiction.loc[y, "avg_price"], 2) if y in yearly_nonfiction.index else None for y in sorted(df["Year"].unique())],
        "fiction_rating": [round(yearly_fiction.loc[y, "avg_rating"], 2) if y in yearly_fiction.index else None for y in sorted(df["Year"].unique())],
        "nonfiction_rating": [round(yearly_nonfiction.loc[y, "avg_rating"], 2) if y in yearly_nonfiction.index else None for y in sorted(df["Year"].unique())],
    },
    "scatter": {
        "price": df["Price"].tolist(),
        "rating": df["User Rating"].tolist(),
        "genre": df["Genre"].tolist(),
    },
    "segment_stats": {
        "labels": segment_order,
        "avg_rating": [round(x, 2) for x in segment_stats["avg_rating"].tolist()],
        "count": segment_stats["count"].tolist(),
    },
    "genre_comparison": {
        "labels": ["Fiction", "Non-Fiction"],
        "avg_price": [round(fiction_avg_price, 2), round(nonfiction_avg_price, 2)],
        "avg_rating": [round(fiction_avg_rating, 2), round(nonfiction_avg_rating, 2)],
        "avg_reviews": [round(genre_stats.loc["Fiction", "avg_reviews"], 0), round(genre_stats.loc["Non Fiction", "avg_reviews"], 0)],
    },
    "top_authors": {
        "names": top_authors["Author"].tolist(),
        "appearances": top_authors["appearances"].tolist(),
        "avg_rating": [round(x, 2) for x in top_authors["avg_rating"].tolist()],
        "avg_price": [round(x, 2) for x in top_authors["avg_price"].tolist()],
    },
    "correlation": {
        "pearson_r": round(pearson_r, 4),
        "pearson_p": round(pearson_p, 6),
        "spearman_r": round(spearman_r, 4),
    }
}

# ── Generate HTML ─────────────────────────────────────────────────────────
os.makedirs("/app/output", exist_ok=True)

chart_json = json.dumps(chart_data)

# Compute KPI cards
kpi_cards = {
    "total_records": total_records,
    "unique_books": unique_books,
    "unique_authors": unique_authors,
    "avg_price": round(avg_price, 2),
    "avg_rating": round(avg_rating, 2),
    "avg_reviews": round(avg_reviews, 0),
    "fiction_pct": round(fiction_count / total_records * 100, 1),
    "nonfiction_pct": round(nonfiction_count / total_records * 100, 1),
    "pearson_r": round(pearson_r, 4),
}

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0f172a;
    --surface: #1e293b;
    --surface2: #334155;
    --accent: #3b82f6;
    --accent2: #8b5cf6;
    --green: #10b981;
    --amber: #f59e0b;
    --red: #ef4444;
    --text: #f1f5f9;
    --text2: #94a3b8;
    --border: #475569;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 24px; }}

  /* Hero */
  .hero {{
    background: linear-gradient(135deg, #1e3a5f 0%, #0f172a 50%, #1a1040 100%);
    padding: 64px 0 48px;
    border-bottom: 1px solid var(--border);
  }}
  .hero h1 {{ font-size: 2.25rem; font-weight: 700; margin-bottom: 8px; letter-spacing: -0.5px; }}
  .hero .subtitle {{ color: var(--text2); font-size: 1.1rem; max-width: 720px; }}
  .hero .meta {{ margin-top: 20px; display: flex; gap: 24px; flex-wrap: wrap; }}
  .hero .meta span {{ color: var(--accent); font-size: 0.85rem; font-weight: 500; }}

  /* KPI Strip */
  .kpi-strip {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 16px;
    margin: 32px 0;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    text-align: center;
  }}
  .kpi-card .value {{ font-size: 1.75rem; font-weight: 700; color: var(--accent); }}
  .kpi-card .label {{ font-size: 0.8rem; color: var(--text2); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }}

  /* Sections */
  .report-section {{
    margin: 48px 0;
    padding: 32px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
  }}
  .report-section h2 {{
    font-size: 1.5rem; font-weight: 700; margin-bottom: 8px;
    padding-bottom: 12px; border-bottom: 2px solid var(--accent);
  }}
  .report-section h2 .num {{
    color: var(--accent); margin-right: 8px; font-weight: 800;
  }}
  .report-section .insight {{
    background: rgba(59, 130, 246, 0.08);
    border-left: 3px solid var(--accent);
    padding: 12px 16px;
    margin: 16px 0;
    border-radius: 0 8px 8px 0;
    font-size: 0.92rem;
    color: var(--text);
  }}
  .report-section .insight strong {{ color: var(--accent); }}
  .report-section p {{ color: var(--text2); margin: 12px 0; font-size: 0.95rem; }}

  /* Chart containers */
  .chart-grid {{ display: grid; gap: 24px; margin: 24px 0; }}
  .chart-grid.cols-2 {{ grid-template-columns: 1fr 1fr; }}
  .chart-grid.cols-1 {{ grid-template-columns: 1fr; }}
  .chart-wrap {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    position: relative;
  }}
  .chart-wrap h3 {{ font-size: 0.95rem; color: var(--text2); margin-bottom: 12px; font-weight: 600; }}
  .chart-wrap canvas {{ width: 100% !important; }}

  /* Tables */
  .data-table {{ width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 0.9rem; }}
  .data-table th {{
    text-align: left; padding: 10px 12px; background: var(--bg);
    color: var(--accent); font-weight: 600; border-bottom: 2px solid var(--border);
    text-transform: uppercase; font-size: 0.75rem; letter-spacing: 0.5px;
  }}
  .data-table td {{ padding: 10px 12px; border-bottom: 1px solid var(--border); color: var(--text2); }}
  .data-table tr:hover td {{ background: rgba(59,130,246,0.05); color: var(--text); }}
  .data-table .highlight {{ color: var(--green); font-weight: 600; }}

  /* Stat badge */
  .stat-badge {{
    display: inline-block; padding: 2px 10px; border-radius: 999px;
    font-size: 0.8rem; font-weight: 600; margin: 2px;
  }}
  .stat-badge.blue {{ background: rgba(59,130,246,0.15); color: var(--accent); }}
  .stat-badge.green {{ background: rgba(16,185,129,0.15); color: var(--green); }}
  .stat-badge.amber {{ background: rgba(245,158,11,0.15); color: var(--amber); }}
  .stat-badge.red {{ background: rgba(239,68,68,0.15); color: var(--red); }}
  .stat-badge.purple {{ background: rgba(139,92,246,0.15); color: var(--accent2); }}

  /* Recommendations */
  .rec-card {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px 24px;
    margin: 16px 0;
  }}
  .rec-card h4 {{ color: var(--accent); font-size: 1rem; margin-bottom: 8px; }}
  .rec-card p {{ color: var(--text2); font-size: 0.9rem; }}
  .rec-card .evidence {{
    margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--border);
    font-size: 0.82rem; color: var(--text2); font-style: italic;
  }}

  /* Footer */
  .footer {{
    text-align: center; padding: 32px 0; color: var(--text2); font-size: 0.8rem;
    border-top: 1px solid var(--border); margin-top: 48px;
  }}

  @media (max-width: 768px) {{
    .chart-grid.cols-2 {{ grid-template-columns: 1fr; }}
    .hero h1 {{ font-size: 1.6rem; }}
    .kpi-strip {{ grid-template-columns: repeat(2, 1fr); }}
  }}
</style>
</head>
<body>

<!-- ═══ Hero ═══ -->
<div class="hero">
  <div class="container">
    <h1>Amazon Bestselling Books: Price vs. User Rating</h1>
    <div class="subtitle">A comprehensive trend analysis examining the relationship between book pricing and customer satisfaction across Fiction and Non-Fiction genres over a decade of Amazon bestseller data (2009–2019).</div>
    <div class="meta">
      <span>550 Records</span>
      <span>351 Unique Titles</span>
      <span>248 Authors</span>
      <span>11 Years</span>
    </div>
  </div>
</div>

<div class="container">

<!-- ═══ KPI Strip ═══ -->
<div class="kpi-strip">
  <div class="kpi-card"><div class="value">{kpi_cards['total_records']}</div><div class="label">Total Records</div></div>
  <div class="kpi-card"><div class="value">{kpi_cards['unique_books']}</div><div class="label">Unique Titles</div></div>
  <div class="kpi-card"><div class="value">${kpi_cards['avg_price']}</div><div class="label">Avg. Price</div></div>
  <div class="kpi-card"><div class="value">{kpi_cards['avg_rating']}</div><div class="label">Avg. Rating</div></div>
  <div class="kpi-card"><div class="value">{int(kpi_cards['avg_reviews']):,}</div><div class="label">Avg. Reviews</div></div>
  <div class="kpi-card"><div class="value">{kpi_cards['pearson_r']}</div><div class="label">Pearson r (Price↔Rating)</div></div>
</div>

<!-- ═══ Section 1: Market Overview ═══ -->
<div class="report-section">
  <h2><span class="num">01</span>Bestseller Market Overview (2009–2019)</h2>
  <p>The dataset captures the top 50 bestselling books on Amazon for each year from 2009 to 2019 — a total of <strong>{total_records} records</strong> spanning <strong>{unique_books} unique titles</strong> by <strong>{unique_authors} distinct authors</strong>. The same title can appear in multiple years if it achieved bestseller status more than once.</p>

  <div class="insight">
    <strong>Genre Split:</strong> Non-Fiction accounts for <span class="stat-badge blue">{nonfiction_count} records ({round(nonfiction_count/total_records*100,1)}%)</span> while Fiction comprises <span class="stat-badge purple">{fiction_count} records ({round(fiction_count/total_records*100,1)}%)</span>. Non-Fiction titles consistently outnumber Fiction on the annual bestseller lists.
  </div>

  <table class="data-table">
    <tr><th>Metric</th><th>Value</th></tr>
    <tr><td>Total Records (book-year entries)</td><td>{total_records}</td></tr>
    <tr><td>Unique Book Titles</td><td>{unique_books}</td></tr>
    <tr><td>Unique Authors</td><td>{unique_authors}</td></tr>
    <tr><td>Average Price</td><td>${round(avg_price, 2)}</td></tr>
    <tr><td>Median Price</td><td>${round(df['Price'].median(), 2)}</td></tr>
    <tr><td>Average User Rating</td><td>{round(avg_rating, 2)} / 5.0</td></tr>
    <tr><td>Average Review Count</td><td>{int(avg_reviews):,}</td></tr>
    <tr><td>Total Reviews Across All Records</td><td>{total_reviews:,}</td></tr>
    <tr><td>Price Range</td><td>${df['Price'].min()} – ${df['Price'].max()}</td></tr>
    <tr><td>Rating Range</td><td>{df['User Rating'].min()} – {df['User Rating'].max()}</td></tr>
    <tr><td>Non-Fiction Records</td><td>{nonfiction_count} ({round(nonfiction_count/total_records*100,1)}%)</td></tr>
    <tr><td>Fiction Records</td><td>{fiction_count} ({round(fiction_count/total_records*100,1)}%)</td></tr>
  </table>

  <div class="insight">
    <strong>Rating Ceiling Effect:</strong> Bestseller ratings are highly compressed — the mean is {round(avg_rating, 2)} with a standard deviation of just {round(df['User Rating'].std(), 2)}. Even a 0.1-point rating difference is meaningful in this narrow range.
  </div>
</div>

<!-- ═══ Section 2: Price vs. Rating Correlation ═══ -->
<div class="report-section">
