import pandas as pd
import numpy as np
from scipy import stats
import json
import os

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv("/app/benchmark/data.csv")
df.columns = df.columns.str.strip()

# Normalize genre spelling
df["Genre"] = df["Genre"].str.strip()

# ── 1. Market Overview ────────────────────────────────────────────────────
total_records = len(df)
unique_books = df["Name"].nunique()
unique_authors = df["Author"].nunique()
avg_price = df["Price"].mean()
avg_rating = df["User Rating"].mean()
total_reviews = df["Reviews"].sum()
avg_reviews = df["Reviews"].mean()
genre_counts = df["Genre"].value_counts()
fiction_count = genre_counts.get("Fiction", 0)
nonfiction_count = genre_counts.get("Non Fiction", 0)
year_range = f"{df['Year'].min()}–{df['Year'].max()}"

# ── 2. Price-Rating Correlation ───────────────────────────────────────────
pearson_r, pearson_p = stats.pearsonr(df["Price"], df["User Rating"])
spearman_r, spearman_p = stats.spearmanr(df["Price"], df["User Rating"])

# Price segments
def price_segment(p):
    if p == 0:
        return "Free ($0)"
    elif p <= 5:
        return "Budget ($1–5)"
    elif p <= 10:
        return "Mid-Low ($6–10)"
    elif p <= 15:
        return "Mid ($11–15)"
    elif p <= 25:
        return "Mid-High ($16–25)"
    else:
        return "Premium ($26+)"

df["PriceSegment"] = df["Price"].apply(price_segment)
segment_order = ["Free ($0)", "Budget ($1–5)", "Mid-Low ($6–10)", "Mid ($11–15)", "Mid-High ($16–25)", "Premium ($26+)"]
segment_stats = df.groupby("PriceSegment").agg(
    count=("Price", "size"),
    avg_rating=("User Rating", "mean"),
    avg_price=("Price", "mean"),
    avg_reviews=("Reviews", "mean")
).reindex(segment_order)

# ── 3. Genre Comparison ──────────────────────────────────────────────────
genre_stats = df.groupby("Genre").agg(
    count=("Price", "size"),
    avg_price=("Price", "mean"),
    median_price=("Price", "median"),
    avg_rating=("User Rating", "mean"),
    avg_reviews=("Reviews", "mean"),
    total_reviews=("Reviews", "sum"),
    min_price=("Price", "min"),
    max_price=("Price", "max"),
    min_rating=("User Rating", "min"),
    max_rating=("User Rating", "max")
)

# ── 4. Temporal Trends ───────────────────────────────────────────────────
yearly = df.groupby("Year").agg(
    avg_price=("Price", "mean"),
    avg_rating=("User Rating", "mean"),
    avg_reviews=("Reviews", "mean"),
    total_reviews=("Reviews", "sum"),
    count=("Price", "size")
).reset_index()

yearly_genre = df.groupby(["Year", "Genre"]).agg(
    avg_price=("Price", "mean"),
    avg_rating=("User Rating", "mean"),
    avg_reviews=("Reviews", "mean"),
    count=("Price", "size")
).reset_index()

yearly_fiction = yearly_genre[yearly_genre["Genre"] == "Fiction"].set_index("Year")
yearly_nonfiction = yearly_genre[yearly_genre["Genre"] == "Non Fiction"].set_index("Year")

# Price distribution per year
yearly_price_std = df.groupby("Year")["Price"].std().reset_index()
yearly_price_std.columns = ["Year", "price_std"]

# ── 5. Top Authors ───────────────────────────────────────────────────────
author_freq = df.groupby("Author").agg(
    appearances=("Name", "size"),
    unique_books=("Name", "nunique"),
    avg_rating=("User Rating", "mean"),
    avg_price=("Price", "mean"),
    total_reviews=("Reviews", "sum")
).sort_values("appearances", ascending=False)

top_authors = author_freq.head(10).reset_index()

# ── 6. Additional computed values for recommendations ────────────────────
# Best value segment
best_value_segment = segment_stats["avg_rating"].idxmax()

# Price change over decade
price_2009 = yearly[yearly["Year"] == 2009]["avg_price"].values[0]
price_2019 = yearly[yearly["Year"] == 2019]["avg_price"].values[0]
price_change_pct = ((price_2019 - price_2009) / price_2009) * 100

rating_2009 = yearly[yearly["Year"] == 2009]["avg_rating"].values[0]
rating_2019 = yearly[yearly["Year"] == 2019]["avg_rating"].values[0]

# Genre price gap
fiction_avg_price = genre_stats.loc["Fiction", "avg_price"]
nonfiction_avg_price = genre_stats.loc["Non Fiction", "avg_price"]
genre_price_gap = abs(fiction_avg_price - nonfiction_avg_price)

fiction_avg_rating = genre_stats.loc["Fiction", "avg_rating"]
nonfiction_avg_rating = genre_stats.loc["Non Fiction", "avg_rating"]

# ── Build data JSON for JS charts ────────────────────────────────────────
chart_data = {
