    display: inline-block; padding: 2px 10px; border-radius: 999px;
    font-size: 0.8rem; font-weight: 600; margin: 2px;
  }}
  .stat-badge.blue {{ background: rgba(59,130,246,0.15); color: var(--accent); }}
  .stat-badge.green {{ background: rgba(16,185,129,0.15); color: var(--green); }}
  .stat-badge.amber {{ background: rgba(245,158,11,0.15); color: var(--amber); }}
  .stat-badge.red {{ background: rgba(239,68,68,0.15); color: var(--red); }}
  .stat-badge.purple {{ background: rgba(139,92,246,0.15); color: var(--accent2); }}

  /* Recommendations */
  .rec-card {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px 24px;
    margin: 16px 0;
  }}
  .rec-card h4 {{ color: var(--accent); font-size: 1rem; margin-bottom: 8px; }}
  .rec-card p {{ color: var(--text2); font-size: 0.9rem; }}
  .rec-card .evidence {{
    margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--border);
    font-size: 0.82rem; color: var(--text2); font-style: italic;
  }}

  /* Footer */
  .footer {{
    text-align: center; padding: 32px 0; color: var(--text2); font-size: 0.8rem;
    border-top: 1px solid var(--border); margin-top: 48px;
  }}

  @media (max-width: 768px) {{
    .chart-grid.cols-2 {{ grid-template-columns: 1fr; }}
    .hero h1 {{ font-size: 1.6rem; }}
    .kpi-strip {{ grid-template-columns: repeat(2, 1fr); }}
  }}
</style>
</head>
<body>

<!-- ═══ Hero ═══ -->
<div class="hero">
  <div class="container">
    <h1>Amazon Bestselling Books: Price vs. User Rating</h1>
    <div class="subtitle">A comprehensive trend analysis examining the relationship between book pricing and customer satisfaction across Fiction and Non-Fiction genres over a decade of Amazon bestseller data (2009–2019).</div>
    <div class="meta">
      <span>550 Records</span>
      <span>351 Unique Titles</span>
      <span>248 Authors</span>
      <span>11 Years</span>
    </div>
  </div>
</div>

<div class="container">

<!-- ═══ KPI Strip ═══ -->
<div class="kpi-strip">
  <div class="kpi-card"><div class="value">{kpi_cards['total_records']}</div><div class="label">Total Records</div></div>
  <div class="kpi-card"><div class="value">{kpi_cards['unique_books']}</div><div class="label">Unique Titles</div></div>
  <div class="kpi-card"><div class="value">${kpi_cards['avg_price']}</div><div class="label">Avg. Price</div></div>
  <div class="kpi-card"><div class="value">{kpi_cards['avg_rating']}</div><div class="label">Avg. Rating</div></div>
  <div class="kpi-card"><div class="value">{int(kpi_cards['avg_reviews']):,}</div><div class="label">Avg. Reviews</div></div>
  <div class="kpi-card"><div class="value">{kpi_cards['pearson_r']}</div><div class="label">Pearson r (Price↔Rating)</div></div>
</div>

<!-- ═══ Section 1: Market Overview ═══ -->
<div class="report-section">
  <h2><span class="num">01</span>Bestseller Market Overview (2009–2019)</h2>
  <p>The dataset captures the top 50 bestselling books on Amazon for each year from 2009 to 2019 — a total of <strong>{total_records} records</strong> spanning <strong>{unique_books} unique titles</strong> by <strong>{unique_authors} distinct authors</strong>. The same title can appear in multiple years if it achieved bestseller status more than once.</p>

  <div class="insight">
    <strong>Genre Split:</strong> Non-Fiction accounts for <span class="stat-badge blue">{nonfiction_count} records ({round(nonfiction_count/total_records*100,1)}%)</span> while Fiction comprises <span class="stat-badge purple">{fiction_count} records ({round(fiction_count/total_records*100,1)}%)</span>. Non-Fiction titles consistently outnumber Fiction on the annual bestseller lists.
  </div>

  <table class="data-table">
    <tr><th>Metric</th><th>Value</th></tr>
    <tr><td>Total Records (book-year entries)</td><td>{total_records}</td></tr>
    <tr><td>Unique Book Titles</td><td>{unique_books}</td></tr>
    <tr><td>Unique Authors</td><td>{unique_authors}</td></tr>
    <tr><td>Average Price</td><td>${round(avg_price, 2)}</td></tr>
    <tr><td>Median Price</td><td>${round(df['Price'].median(), 2)}</td></tr>
    <tr><td>Average User Rating</td><td>{round(avg_rating, 2)} / 5.0</td></tr>
    <tr><td>Average Review Count</td><td>{int(avg_reviews):,}</td></tr>
    <tr><td>Total Reviews Across All Records</td><td>{total_reviews:,}</td></tr>
    <tr><td>Price Range</td><td>${df['Price'].min()} – ${df['Price'].max()}</td></tr>
    <tr><td>Rating Range</td><td>{df['User Rating'].min()} – {df['User Rating'].max()}</td></tr>
    <tr><td>Non-Fiction Records</td><td>{nonfiction_count} ({round(nonfiction_count/total_records*100,1)}%)</td></tr>
    <tr><td>Fiction Records</td><td>{fiction_count} ({round(fiction_count/total_records*100,1)}%)</td></tr>
  </table>

  <div class="insight">
    <strong>Rating Ceiling Effect:</strong> Bestseller ratings are highly compressed — the mean is {round(avg_rating, 2)} with a standard deviation of just {round(df['User Rating'].std(), 2)}. Even a 0.1-point rating difference is meaningful in this narrow range.
  </div>
</div>

<!-- ═══ Section 2: Price vs. Rating Correlation ═══ -->
<div class="report-section">
  <h2><span class="num">02</span>Price vs. User Rating: Correlation Analysis</h2>
  <p>The central question: does paying more for a bestselling book correlate with higher customer satisfaction? We examine both the overall statistical relationship and how it varies across price segments.</p>

  <div class="insight">
    <strong>Pearson Correlation: r = {round(pearson_r, 4)}</strong> (p = {round(pearson_p, 6)}). This indicates a <em>{'very weak' if abs(pearson_r) < 0.1 else 'weak' if abs(pearson_r) < 0.3 else 'moderate' if abs(pearson_r) < 0.5 else 'strong'} negative</em> linear relationship — higher-priced books tend to receive slightly lower ratings, though the effect is minimal. Price explains only {round(pearson_r**2 * 100, 2)}% of the variance in ratings (R² = {round(pearson_r**2, 4)}).
  </div>

  <div class="chart-grid cols-2">
    <div class="chart-wrap">
      <h3>Price vs. User Rating Scatter Plot</h3>
      <canvas id="scatterChart" height="300"></canvas>
    </div>
    <div class="chart-wrap">
      <h3>Average Rating by Price Segment</h3>
      <canvas id="segmentChart" height="300"></canvas>
    </div>
  </div>

  <table class="data-table">
    <tr><th>Price Segment</th><th>Count</th><th>Avg. Rating</th><th>Avg. Price</th><th>Avg. Reviews</th></tr>
    {''.join(f'<tr><td>{seg}</td><td>{int(row["count"])}</td><td class="{"highlight" if row["avg_rating"] == segment_stats["avg_rating"].max() else ""}">{round(row["avg_rating"], 2)}</td><td>${round(row["avg_price"], 2)}</td><td>{int(row["avg_reviews"]):,}</td></tr>' for seg, row in segment_stats.iterrows())}
  </table>

  <div class="insight">
    <strong>Segment Insight:</strong> The <span class="stat-badge green">{best_value_segment}</span> segment achieves the highest average rating at {round(segment_stats.loc[best_value_segment, "avg_rating"], 2)}, while the Premium ($26+) segment trails at {round(segment_stats.loc["Premium ($26+)", "avg_rating"], 2)}. Free and budget books hold their own — customer satisfaction is not driven by price.
  </div>
</div>

<!-- ═══ Section 3: Genre Comparison ═══ -->
<div class="report-section">
  <h2><span class="num">03</span>Fiction vs. Non-Fiction: Pricing and Rating Strategies</h2>
  <p>How do the two genres differ in their pricing and rating profiles? This section provides a direct side-by-side comparison for rapid executive assessment.</p>

  <div class="chart-grid cols-2">
    <div class="chart-wrap">
      <h3>Average Price by Genre</h3>
      <canvas id="genrePriceChart" height="260"></canvas>
    </div>
    <div class="chart-wrap">
      <h3>Average Rating by Genre</h3>
      <canvas id="genreRatingChart" height="260"></canvas>
    </div>
  </div>

  <table class="data-table">
    <tr><th>Metric</th><th>Fiction</th><th>Non-Fiction</th><th>Difference</th></tr>
    <tr><td>Records</td><td>{fiction_count}</td><td>{nonfiction_count}</td><td>{nonfiction_count - fiction_count}</td></tr>
    <tr><td>Avg. Price</td><td>${round(fiction_avg_price, 2)}</td><td>${round(nonfiction_avg_price, 2)}</td><td>${round(genre_price_gap, 2)}</td></tr>
    <tr><td>Median Price</td><td>${round(genre_stats.loc['Fiction', 'median_price'], 2)}</td><td>${round(genre_stats.loc['Non Fiction', 'median_price'], 2)}</td><td>${round(abs(genre_stats.loc['Fiction', 'median_price'] - genre_stats.loc['Non Fiction', 'median_price']), 2)}</td></tr>
    <tr><td>Avg. Rating</td><td>{round(fiction_avg_rating, 2)}</td><td>{round(nonfiction_avg_rating, 2)}</td><td>{round(fiction_avg_rating - nonfiction_avg_rating, 2)}</td></tr>
    <tr><td>Avg. Reviews</td><td>{int(genre_stats.loc['Fiction', 'avg_reviews']):,}</td><td>{int(genre_stats.loc['Non Fiction', 'avg_reviews']):,}</td><td>{int(genre_stats.loc['Fiction', 'avg_reviews'] - genre_stats.loc['Non Fiction', 'avg_reviews']):,}</td></tr>
    <tr><td>Price Range</td><td>${int(genre_stats.loc['Fiction', 'min_price'])} – ${int(genre_stats.loc['Fiction', 'max_price'])}</td><td>${int(genre_stats.loc['Non Fiction', 'min_price'])} – ${int(genre_stats.loc['Non Fiction', 'max_price'])}</td><td>—</td></tr>
    <tr><td>Rating Range</td><td>{genre_stats.loc['Fiction', 'min_rating']} – {genre_stats.loc['Fiction', 'max_rating']}</td><td>{genre_stats.loc['Non Fiction', 'min_rating']} – {genre_stats.loc['Non Fiction', 'max_rating']}</td><td>—</td></tr>
  </table>

  <div class="insight">
    <strong>Key Difference:</strong> {'Non-Fiction' if nonfiction_avg_price > fiction_avg_price else 'Fiction'} books are priced <span class="stat-badge amber">${round(genre_price_gap, 2)} higher</span> on average, yet {'Fiction' if fiction_avg_rating > nonfiction_avg_rating else 'Non-Fiction'} books earn {'higher' if fiction_avg_rating > nonfiction_avg_rating else 'lower'} ratings ({round(max(fiction_avg_rating, nonfiction_avg_rating), 2)} vs. {round(min(fiction_avg_rating, nonfiction_avg_rating), 2)}). Fiction also generates {'more' if genre_stats.loc['Fiction', 'avg_reviews'] > genre_stats.loc['Non Fiction', 'avg_reviews'] else 'fewer'} reviews on average, suggesting {'higher' if genre_stats.loc['Fiction', 'avg_reviews'] > genre_stats.loc['Non Fiction', 'avg_reviews'] else 'lower'} reader engagement.
  </div>
</div>

<!-- ═══ Section 4: Temporal Trends ═══ -->
<div class="report-section">
  <h2><span class="num">04</span>Year-over-Year Trends in Pricing and Ratings</h2>
  <p>This section tracks how pricing, ratings, and engagement have shifted annually across the 2009–2019 window — the most critical analysis for identifying inflection points in market dynamics.</p>

  <div class="chart-grid cols-1">
    <div class="chart-wrap">
      <h3>Average Book Price Over Time (Overall & by Genre)</h3>
      <canvas id="priceTrendChart" height="320"></canvas>
    </div>
  </div>

  <div class="chart-grid cols-1">
    <div class="chart-wrap">
      <h3>Average User Rating Over Time (Overall & by Genre)</h3>
      <canvas id="ratingTrendChart" height="320"></canvas>
    </div>
  </div>

  <div class="chart-grid cols-1">
    <div class="chart-wrap">
      <h3>Average Review Count Over Time</h3>
      <canvas id="reviewTrendChart" height="280"></canvas>
    </div>
  </div>

  <table class="data-table">
    <tr><th>Year</th><th>Avg. Price</th><th>Avg. Rating</th><th>Avg. Reviews</th><th>Records</th><th>Price YoY Δ</th><th>Rating YoY Δ</th></tr>
    {''.join(f'''<tr>
      <td>{int(row['Year'])}</td>
      <td>${round(row['avg_price'], 2)}</td>
      <td>{round(row['avg_rating'], 2)}</td>
      <td>{int(row['avg_reviews']):,}</td>
      <td>{int(row['count'])}</td>
      <td>{"—" if i == 0 else f"{round((row['avg_price'] - yearly.iloc[i-1]['avg_price']) / yearly.iloc[i-1]['avg_price'] * 100, 1)}%"}</td>
      <td>{"—" if i == 0 else f"{round(row['avg_rating'] - yearly.iloc[i-1]['avg_rating'], 3):+}"}</td>
    </tr>''' for i, (_, row) in enumerate(yearly.iterrows()))}
  </table>

  <div class="insight">
    <strong>Price Decline:</strong> Average bestseller price fell from ${round(price_2009, 2)} in 2009 to ${round(price_2019, 2)} in 2019 — a {round(abs(price_change_pct), 1)}% {'decrease' if price_change_pct < 0 else 'increase'}. The sharpest year-over-year drop occurred between {yearly.loc[yearly['avg_price'].diff().idxmin(), 'Year'].astype(int)} and {yearly.loc[yearly['avg_price'].diff().idxmin() + 1, 'Year'].astype(int) if yearly['avg_price'].diff().idxmin() + 1 < len(yearly) else yearly.iloc[-1]['Year'].astype(int)}.
  </div>

  <div class="insight">
    <strong>Rating Climb:</strong> While prices declined, average ratings {'rose' if rating_2019 > rating_2009 else 'declined'} from {round(rating_2009, 2)} to {round(rating_2019, 2)} — suggesting that lower-priced bestsellers are not perceived as lower quality. The inverse relationship between price and rating trends further underscores the weak negative correlation identified in Section 02.
  </div>
</div>

<!-- ═══ Section 5: Top Authors ═══ -->
<div class="report-section">
  <h2><span class="num">05</span>Dominant Authors on the Bestseller List</h2>
  <p>Which authors have the strongest sustained presence on the bestseller list, and what do their pricing and rating patterns reveal?</p>

  <div class="chart-grid cols-2">
    <div class="chart-wrap">
      <h3>Top 10 Authors by Bestseller Appearances</h3>
      <canvas id="authorBarChart" height="360"></canvas>
    </div>
    <div class="chart-wrap">
      <h3>Top Authors: Avg. Price vs. Avg. Rating</h3>
      <canvas id="authorScatterChart" height="360"></canvas>
    </div>
  </div>

  <table class="data-table">
    <tr><th>Author</th><th>Appearances</th><th>Unique Books</th><th>Avg. Rating</th><th>Avg. Price</th><th>Total Reviews</th></tr>
    {''.join(f'<tr><td>{row["Author"]}</td><td>{int(row["appearances"])}</td><td>{int(row["unique_books"])}</td><td>{round(row["avg_rating"], 2)}</td><td>${round(row["avg_price"], 2)}</td><td>{int(row["total_reviews"]):,}</td></tr>' for _, row in top_authors.iterrows())}
  </table>

  <div class="insight">
    <strong>Author Pricing Patterns:</strong> The most prolific bestseller authors cluster in the $6–$15 price range, well below the dataset's premium tier. Their average ratings consistently exceed 4.5 — reinforcing that sustained bestseller status is built on perceived value, not premium pricing.
  </div>
</div>

<!-- ═══ Section 6: Recommendations ═══ -->
<div class="report-section">
  <h2><span class="num">06</span>Strategic Recommendations</h2>
  <p>Every recommendation below is grounded in the data findings from the preceding analysis. No speculative advice — each traces to a specific finding.</p>

  <div class="rec-card">
    <h4>1. Price Competitively in the $6–$15 Sweet Spot</h4>
    <p>The {best_value_segment} segment achieves the highest average rating. The top 10 bestseller authors cluster in the $6–$15 range. Books priced above $25 consistently earn lower ratings. For new titles targeting bestseller status, aim for this competitive band rather than premium pricing.</p>
    <div class="evidence">Finding: Pearson r = {round(pearson_r, 4)} (negative); top authors' avg price range $6–$15; Premium segment avg rating {round(segment_stats.loc["Premium ($26+)", "avg_rating"], 2)} vs. overall avg {round(avg_rating, 2)}</div>
  </div>

  <div class="rec-card">
    <h4>2. Invest in Fiction for Higher Satisfaction and Engagement</h4>
    <p>Fiction books earn {'higher' if fiction_avg_rating > nonfiction_avg_rating else 'lower'} average ratings ({round(fiction_avg_rating, 2)} vs. {round(nonfiction_avg_rating, 2)}) and generate {'more' if genre_stats.loc['Fiction', 'avg_reviews'] > genre_stats.loc['Non Fiction', 'avg_reviews'] else 'fewer'} reviews — a proxy for reader engagement. For catalog curation, Fiction titles deliver better perceived value per dollar spent, even at {'lower' if fiction_avg_price < nonfiction_avg_price else 'higher'} average prices.</p>
    <div class="evidence">Finding: Fiction avg rating {round(fiction_avg_rating, 2)} vs. Non-Fiction {round(nonfiction_avg_rating, 2)}; Fiction avg reviews {int(genre_stats.loc['Fiction', 'avg_reviews']):,} vs. Non-Fiction {int(genre_stats.loc['Non Fiction', 'avg_reviews']):,}</div>
  </div>

  <div class="rec-card">
    <h4>3. Adapt to the Decade-Long Price Decline</h4>
    <p>Average bestseller prices {'fell' if price_change_pct < 0 else 'rose'} by {round(abs(price_change_pct), 1)}% from 2009 to 2019 (${round(price_2009, 2)} → ${round(price_2019, 2)}), likely driven by e-book growth and competitive pressure. Pricing strategies must account for this structural shift — static pricing models will leave titles uncompetitive.</p>
    <div class="evidence">Finding: 2009 avg price ${round(price_2009, 2)}, 2019 avg price ${round(price_2019, 2)}, {round(abs(price_change_pct), 1)}% {'decline' if price_change_pct < 0 else 'increase'}</div>
  </div>

  <div class="rec-card">
    <h4>4. Leverage Ratings as a Marketing Asset, Not Price Justification</h4>
    <p>With a Pearson r of {round(pearson_r, 4)}, price explains only {round(pearson_r**2 * 100, 2)}% of rating variance. Higher prices do not produce higher ratings. Instead, invest in quality content and editorial standards — the data shows that low- and mid-priced books can achieve top-tier ratings without the price premium.</p>
    <div class="evidence">Finding: R² = {round(pearson_r**2, 4)}; Budget and Mid-Low segments both exceed 4.6 average rating</div>
  </div>

  <div class="rec-card">
    <h4>5. Monitor Rating Erosion in Premium Segments</h4>
    <p>Premium-priced books ($26+) average only {round(segment_stats.loc["Premium ($26+)", "avg_rating"], 2)} vs. the overall {round(avg_rating, 2)}. If premium pricing is unavoidable (e.g., boxed sets, illustrated editions), ensure the content quality justifies the price gap — customers are demonstrably less forgiving at higher price points.</p>
    <div class="evidence">Finding: Premium segment avg rating {round(segment_stats.loc["Premium ($26+)", "avg_rating"], 2)}, {round(segment_stats.loc["Premium ($26+)", "avg_rating"] - avg_rating, 2)} below overall average</div>
  </div>
</div>

</div><!-- /container -->

<div class="footer">
  <div class="container">
    Amazon Bestselling Books — Price vs. User Rating Trend Analysis (2009–2019)<br>
    Data source: Amazon Top 50 Bestselling Books | Analysis computed directly from dataset<br>
    Generated {pd.Timestamp.now().strftime('%Y-%m-%d')}
  </div>
</div>

<script>
// ── Chart Data ──────────────────────────────────────────────────────
const DATA = {chart_json};

const COLORS = {{
  blue: '#3b82f6',
  purple: '#8b5cf6',
  green: '#10b981',
  amber: '#f59e0b',
  red: '#ef4444',
  gray: '#64748b',
  bg: '#0f172a',
  grid: '#1e293b',
  text: '#94a3b8',
}};

Chart.defaults.color = COLORS.text;
Chart.defaults.borderColor = COLORS.grid;
Chart.defaults.font.family = "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";

const commonOptions = (yTitle) => ({{
  responsive: true,
  maintainAspectRatio: false,
  plugins: {{
    legend: {{ position: 'top', labels: {{ usePointStyle: true, padding: 16, font: {{ size: 11 }} }} }},
  }},
  scales: {{
    x: {{ grid: {{ display: false }}, ticks: {{ font: {{ size: 11 }} }} }},
    y: {{ grid: {{ color: COLORS.grid }}, ticks: {{ font: {{ size: 11 }} }}, title: {{ display: true, text: yTitle, font: {{ size: 12 }} }} }}
  }}
}});

// ── Scatter Plot ────────────────────────────────────────────────────
(() => {{
  const fiction = DATA.scatter.price.map((p, i) => DATA.scatter.genre[i] === 'Fiction' ? {{x: p, y: DATA.scatter.rating[i]}} : null).filter(Boolean);
  const nf = DATA.scatter.price.map((p, i) => DATA.scatter.genre[i] !== 'Fiction' ? {{x: p, y: DATA.scatter.rating[i]}} : null).filter(Boolean);
  new Chart(document.getElementById('scatterChart'), {{
    type: 'scatter',
    data: {{
      datasets: [
        {{ label: 'Fiction', data: fiction, backgroundColor: COLORS.blue + '80', borderColor: COLORS.blue, pointRadius: 4, pointHoverRadius: 6 }},
        {{ label: 'Non-Fiction', data: nf, backgroundColor: COLORS.purple + '80', borderColor: COLORS.purple, pointRadius: 4, pointHoverRadius: 6 }},
      ]
    }},
    options: {{
      responsive: true, maintainAspectRatio: false,
      plugins: {{
        legend: {{ position: 'top', labels: {{ usePointStyle: true, padding: 16, font: {{ size: 11 }} }} }},
        title: {{ display: true, text: 'Pearson r = ' + DATA.correlation.pearson_r, font: {{ size: 13 }}, color: COLORS.amber, padding: {{ bottom: 8 }} }}
      }},
      scales: {{
        x: {{ title: {{ display: true, text: 'Price ($)', font: {{ size: 12 }} }}, grid: {{ color: COLORS.grid }} }},
        y: {{ title: {{ display: true, text: 'User Rating', font: {{ size: 12 }} }}, grid: {{ color: COLORS.grid }}, min: 3.0, max: 5.1 }}
      }}
    }}
  }});
}})();

// ── Segment Bar Chart ───────────────────────────────────────────────
(() => {{
  new Chart(document.getElementById('segmentChart'), {{
    type: 'bar',
    data: {{
      labels: DATA.segment_stats.labels,
      datasets: [{{
        label: 'Avg. Rating',
        data: DATA.segment_stats.avg_rating,
        backgroundColor: [COLORS.green, COLORS.green, COLORS.blue, COLORS.blue, COLORS.amber, COLORS.red].map(c => c + 'CC'),
        borderColor: [COLORS.green, COLORS.green, COLORS.blue, COLORS.blue, COLORS.amber, COLORS.red],
        borderWidth: 1,
        borderRadius: 6,
      }}]
    }},
    options: {{
      ...commonOptions('Avg. Rating'),
      scales: {{
        ...commonOptions('Avg. Rating').scales,
        y: {{ ...commonOptions('Avg. Rating').scales.y, min: 4.0, max: 5.0 }}
      }}
    }}
  }});
}})();

// ── Genre Comparison Charts ─────────────────────────────────────────
(() => {{
  new Chart(document.getElementById('genrePriceChart'), {{
    type: 'bar',
    data: {{
      labels: DATA.genre_comparison.labels,
      datasets: [{{
        label: 'Avg. Price ($)',
        data: DATA.genre_comparison.avg_price,
        backgroundColor: [COLORS.blue + 'CC', COLORS.purple + 'CC'],
        borderColor: [COLORS.blue, COLORS.purple],
        borderWidth: 1,
        borderRadius: 8,
        barPercentage: 0.5,
      }}]
    }},
    options: commonOptions('Price ($)')
  }});
  new Chart(document.getElementById('genreRatingChart'), {{
    type: 'bar',
    data: {{
      labels: DATA.genre_comparison.labels,
      datasets: [{{
        label: 'Avg. Rating',
        data: DATA.genre_comparison.avg_rating,
        backgroundColor: [COLORS.green + 'CC', COLORS.amber + 'CC'],
        borderColor: [COLORS.green, COLORS.amber],
        borderWidth: 1,
        borderRadius: 8,
        barPercentage: 0.5,
      }}]
    }},
    options: {{
      ...commonOptions('Rating'),
      scales: {{
        ...commonOptions('Rating').scales,
        y: {{ ...commonOptions('Rating').scales.y, min: 4.0, max: 5.0 }}
      }}
    }}
  }});
}})();

// ── Price Trend ─────────────────────────────────────────────────────
(() => {{
  new Chart(document.getElementById('priceTrendChart'), {{
    type: 'line',
    data: {{
      labels: DATA.yearly.years,
      datasets: [
